using System.Text.Json;
using SimplePZMapmaker.Core.Export;
namespace SimplePZMapmaker.Core;

/// <summary>Authoritative sparse world strokes. Geometry is generated in world tiles before clipping to sections.</summary>
public static class WorldInfrastructure
{
 static LinearFeature Copy(LinearFeature feature)=>JsonSerializer.Deserialize<LinearFeature>(JsonSerializer.Serialize(feature,NativeMapExporter.JsonOptions),NativeMapExporter.JsonOptions)!;
 public static WorldProject Put(WorldProject source,LinearFeature feature){WorldAssembler.Validate(source);ValidateSource(feature);var world=WorldAssembler.Clone(source);var next=Copy(feature);next.Modified=true;var index=world.LinearFeatures.FindIndex(f=>f.Id==next.Id);if(index<0)world.LinearFeatures.Add(next);else world.LinearFeatures[index]=next;WorldAssembler.Validate(world);return world;}
 public static WorldProject Remove(WorldProject source,string id){WorldAssembler.Validate(source);var world=WorldAssembler.Clone(source);if(world.LinearFeatures.RemoveAll(f=>f.Id==id)!=1)throw new ArgumentException("Shared world path not found.");WorldAssembler.Validate(world);return world;}
 public static IEnumerable<string> ResourceIds(WorldProject world)=>Build(world).Tiles.Select(t=>t.Id).Concat(world.LinearFeatures.Where(f=>f.Kind=="railway").SelectMany(f=>f.Points.Zip(f.Points.Skip(1)).SelectMany(s=>Math.Abs(s.First.Y-s.Second.Y)<.001?new[]{"industry_railroad_01_3","industry_railroad_01_5"}:new[]{"industry_railroad_01_0","industry_railroad_01_2"}))).Distinct(StringComparer.Ordinal);
 public static void ValidateSource(LinearFeature feature){LinearFeatureEditor.ValidateFeature(feature);if(feature.Points.Any(p=>p.X<0||p.Y<0||p.X>258048||p.Y>258048)||feature.Underlay.Count!=0||feature.DecorationIds.Count!=0||feature.GeneratedDecorations.Count!=0||feature.AssetSources.Count!=0)throw new ArgumentException("Shared paths use absolute world tiles and cannot own section underlay or generated artwork.");}
 public static void Validate(WorldProject world){
  if(world.LinearFeatures is null||world.LinearFeatures.Count>64||world.LinearFeatures.Any(f=>f is null)||world.LinearFeatures.Select(f=>f.Id).Distinct().Count()!=world.LinearFeatures.Count)throw new ArgumentException("A world supports up to 64 uniquely identified shared paths.");
  foreach(var f in world.LinearFeatures)ValidateSource(f);if(world.LinearFeatures.Count==0)return;
  var geometry=Build(world);foreach(var member in world.Maps){var projected=WorldAssembler.ProjectSection(world,member,geometry);InfrastructureGeometry.Validate(projected);if(projected.SharedInfrastructure!.Tiles.Any(t=>t.Z==0&&t.Id==InfrastructureGeometry.DeckTile&&projected.Terrain[t.Y*projected.Width+t.X]==Terrain.Water))throw new ArgumentException("Shared stairs need a dry landing after world ground paths are applied.");}
 }
 public static HashSet<(int X,int Y)> Rasterize(LinearFeature feature){
  ValidateSource(feature);var points=LinearFeatureEditor.Sample(feature);var cells=new HashSet<(int,int)>();var radius=feature.Width/2;long work=0;
  for(var segment=1;segment<points.Count;segment++){var a=points[segment-1];var b=points[segment];var steps=(int)Math.Ceiling(Math.Max(Math.Abs(b.X-a.X),Math.Abs(b.Y-a.Y))*2);for(var step=0;step<=steps;step++){var t=steps==0?0:step/(double)steps;var x=a.X+(b.X-a.X)*t;var y=a.Y+(b.Y-a.Y)*t;var left=(int)Math.Floor(x-radius);var right=(int)Math.Ceiling(x+radius);var top=(int)Math.Floor(y-radius);var bottom=(int)Math.Ceiling(y+radius);work+=(long)(right-left+1)*(bottom-top+1);if(work>5_000_000)throw new ArgumentException("Shared path exceeds its sampling budget. Reduce its width, length, or nodes.");for(var yy=top;yy<=bottom;yy++)for(var xx=left;xx<=right;xx++)if(Math.Pow(xx+.5-x,2)+Math.Pow(yy+.5-y,2)<=radius*radius){cells.Add((xx,yy));if(cells.Count>100000)throw new ArgumentException("A shared path covers more than 100,000 tiles.");}}}
  return cells;
 }
 static WorldMapMember Covered(WorldProject world,int x,int y)=>WorldAssembler.MemberAt(world,x,y)??throw new ArgumentException($"A shared path reaches an unmapped world tile ({x},{y}). Add an adjacent section or move the path.");
 static Terrain Ground(WorldProject world,int x,int y){var p=Covered(world,x,y).Project;return p.Terrain[(y-p.WorldY*256)*p.Width+x-p.WorldX*256];}
 public static InfrastructureGeometry.Geometry Build(WorldProject world,Func<int,int,Terrain>? readGround=null){
  Terrain Sample(int x,int y)=>readGround is null?Ground(world,x,y):readGround(x,y);
  var worldCells=new Dictionary<string,HashSet<(int X,int Y)>>();var tiles=new Dictionary<(int,int,int,string),InfrastructureGeometry.Tile>();var holes=new HashSet<InfrastructureGeometry.Hole>();var floors=new HashSet<(int X,int Y,int Z)>();var paths=new List<(LinearFeature Feature,HashSet<(int X,int Y)> Cells)>();long total=0;
  void Add(int x,int y,int z,string tile,byte flags=0){Covered(world,x,y);if(!ZLevels.Contains(z)||tiles.Count>=InfrastructureGeometry.MaximumTiles)throw new ArgumentException("Shared infrastructure exceeds the native tile or signed floor budget.");tiles.TryAdd((x,y,z,tile),new(x,y,z,tile,flags));}
  void Floor(int x,int y,int z){floors.Add((x,y,z));Add(x,y,z,InfrastructureGeometry.DeckTile);}
  foreach(var feature in world.LinearFeatures){var cells=Rasterize(feature);worldCells.Add(feature.Id,cells);total+=cells.Count;if(total>100000)throw new ArgumentException("Shared paths exceed 100,000 managed world tiles.");foreach(var (x,y) in cells)Covered(world,x,y);}
  bool SharedGroundRoad(int x,int y)=>world.LinearFeatures.Any(f=>f.Level==0&&f.Kind is "road" or "bridge" or "sidewalk"&&worldCells[f.Id].Contains((x,y)));
  foreach(var feature in world.LinearFeatures.Where(f=>f.Level!=0)){var cells=worldCells[feature.Id];paths.Add((feature,cells));foreach(var (x,y) in cells)Floor(x,y,feature.Level);
   if(feature.Access=="stairs"){var x=(int)Math.Floor(feature.Points[0].X);var anchor=(int)Math.Floor(feature.Points[0].Y)-(feature.Level<0?-4*feature.Level:0);var low=Math.Min(0,feature.Level);var high=Math.Max(0,feature.Level);for(var z=low;z<high;z++){var y=anchor+4*(high-z-1);Floor(x,y,z+1);Floor(x,y+4,z);for(var step=1;step<=3;step++){Add(x,y+step,z,$"carpentry_02_{99-step}");Covered(world,x,y+step);holes.Add(new(x,y+step,z+1));}}var ground=feature.Level>0?anchor+4*feature.Level:anchor;if(Sample(x,ground)==Terrain.Water)throw new ArgumentException("Shared pedestrian stairs require a dry ground landing.");}
   if(feature.SupportSpacing>0){var horizontal=Math.Abs(feature.Points[^1].X-feature.Points[0].X)>=Math.Abs(feature.Points[^1].Y-feature.Points[0].Y);foreach(var (x,y) in cells){if((horizontal?x:y)%feature.SupportSpacing!=0||cells.Contains(horizontal?(x,y-1):(x-1,y))||Sample(x,y) is Terrain.Road or Terrain.Pavement||SharedGroundRoad(x,y))continue;for(var z=0;z<feature.Level;z++){Add(x,y,z,"walls_exterior_house_01_0",4);Add(x,y,z,"walls_exterior_house_01_1",2);}}}
  }
  foreach(var (feature,cells) in paths.Where(p=>p.Feature.GuardRails))foreach(var (x,y) in cells)foreach(var (dx,dy,tile,flags) in new[]{(0,-1,"fencing_01_1",(byte)2),(-1,0,"fencing_01_2",(byte)4),(0,1,"fencing_01_1",(byte)2),(1,0,"fencing_01_2",(byte)4)}){
   if(floors.Contains((x+dx,y+dy,feature.Level)))continue;var rx=x+(dx==1?1:0);var ry=y+(dy==1?1:0);if(holes.Any(h=>h.X==rx&&Math.Abs(h.Y-ry)<=1&&h.Z==feature.Level)||feature.Access=="stairs"&&rx==(int)Math.Floor(feature.Points[0].X)&&Math.Abs(ry-feature.Points[0].Y)<=Math.Ceiling(feature.Width/2)+1)continue;
   if(feature.Level<0){for(var z=feature.Level;z<0;z++)Add(rx,ry,z,flags==2?"walls_exterior_house_01_1":"walls_exterior_house_01_0",flags);}else Add(rx,ry,feature.Level,tile,flags);
  }
  foreach(var hole in holes){tiles.Remove((hole.X,hole.Y,hole.Z,InfrastructureGeometry.DeckTile));foreach(var (feature,cells) in paths)if(feature.Access=="none"&&feature.Level==hole.Z&&cells.Contains((hole.X,hole.Y)))throw new ArgumentException("A shared stair shaft intersects another deck.");}
  return new(tiles.Values.OrderBy(t=>t.Z).ThenBy(t=>t.Y).ThenBy(t=>t.X).ThenBy(t=>t.Id,StringComparer.Ordinal).ToList(),holes.OrderBy(h=>h.Z).ThenBy(h=>h.Y).ThenBy(h=>h.X).ToList()){WorldCells=worldCells};
 }
 internal static MapProject Project(WorldProject world,WorldMapMember member,MapProject projected,InfrastructureGeometry.Geometry? geometry){
  if(world.LinearFeatures.Count==0)return projected;var p=member.Project;var ox=p.WorldX*256;var oy=p.WorldY*256;bool Inside(int x,int y)=>x>=ox&&y>=oy&&x<ox+p.Width&&y<oy+p.Height;geometry??=Build(world);
  // A projection owns no authoring state. Its ground array and tile sources are private copies.
  projected.Terrain=projected.Terrain.ToArray();projected.SurfaceTiles=new(projected.SurfaceTiles);projected.AssetSources=new(projected.AssetSources);projected.Decorations=[..projected.Decorations];var mask=TerrainEditMask.Decode(p);var blocked=new HashSet<int>();foreach(var b in projected.Buildings)foreach(var i in BuildingDesigner.Occupied(b)){var x=b.X+i%(b.Width+1);var y=b.Y+i/(b.Width+1);if(x>=0&&y>=0&&x<p.Width&&y<p.Height)blocked.Add(y*p.Width+x);}foreach(var s in p.Spawns)blocked.Add(s.Y*p.Width+s.X);foreach(var d in projected.Decorations)foreach(var part in d.Parts)blocked.Add((d.Y+part.Dy)*p.Width+d.X+part.Dx);foreach(var m in p.StaticModels)foreach(var cell in StaticModelPlacement.FootprintCells(m))blocked.Add((m.Y+cell.Dy)*p.Width+m.X+cell.Dx);
  foreach(var feature in world.LinearFeatures.Where(f=>f.Level==0)){var cells=geometry.WorldCells?.GetValueOrDefault(feature.Id)??Rasterize(feature);var terrain=feature.Kind switch{"river"=>Terrain.Water,"sidewalk"=>Terrain.Pavement,"railway"=>Terrain.Dirt,_=>Terrain.Road};foreach(var (x,y) in cells.Where(c=>Inside(c.X,c.Y))){var lx=x-ox;var ly=y-oy;var i=ly*p.Width+lx;if(blocked.Contains(i)||TerrainEditMask.IsEdited(mask,i)||p.SurfaceTiles.ContainsKey(i))continue;var old=projected.Terrain[i];if(feature.Kind is "road" or "sidewalk" or "railway"&&old==Terrain.Water||feature.Kind=="river"&&old is Terrain.Road or Terrain.Pavement||feature.Kind=="sidewalk"&&old==Terrain.Road)continue;projected.Terrain[i]=terrain;}
   if(feature.Kind=="railway")foreach(var segment in feature.Points.Zip(feature.Points.Skip(1))){var horizontal=segment.First.Y==segment.Second.Y;var low=(int)Math.Floor(horizontal?Math.Min(segment.First.X,segment.Second.X):Math.Min(segment.First.Y,segment.Second.Y));var high=(int)Math.Ceiling(horizontal?Math.Max(segment.First.X,segment.Second.X):Math.Max(segment.First.Y,segment.Second.Y));var axis=(int)Math.Round(horizontal?segment.First.Y:segment.First.X);for(var at=low;at<=high;at++)for(var side=0;side<2;side++){var x=horizontal?at:axis+side;var y=horizontal?axis+side:at;if(!Inside(x,y))continue;var lx=x-ox;var ly=y-oy;var i=ly*p.Width+lx;if(!cells.Contains((x,y))||blocked.Contains(i)||TerrainEditMask.IsEdited(mask,i)||p.SurfaceTiles.ContainsKey(i)||projected.Terrain[i]==Terrain.Water)continue;var tile=$"industry_railroad_01_{(horizontal?(side==0?3:5):(side==0?0:2))}";if(projected.AssetSources.TryGetValue(tile,out var provider)&&provider!="game")throw new ArgumentException("Shared railway artwork requires its original game tile provider.");projected.AssetSources[tile]="game";projected.Decorations.Add(new(){Id=$"world-{feature.Id}-{x}-{y}",X=lx,Y=ly,Asset=tile,Parts=[new(0,0,tile)]});blocked.Add(i);}}
  }
  projected.SharedInfrastructure=new(geometry.Tiles.Where(t=>Inside(t.X,t.Y)).Select(t=>t with{X=t.X-ox,Y=t.Y-oy}).ToList(),geometry.Holes.Where(h=>Inside(h.X,h.Y)).Select(h=>h with{X=h.X-ox,Y=h.Y-oy}).ToList());foreach(var tile in projected.SharedInfrastructure.Tiles.Select(t=>t.Id).Distinct()){if(projected.AssetSources.TryGetValue(tile,out var source)&&source!="game")throw new ArgumentException("Shared infrastructure requires its original game tile provider.");projected.AssetSources[tile]="game";}
  return projected;
 }
}
